import { readFileSync } from 'node:fs'
import { test } from '@e2e-dev/web'
import { expect } from 'e2e'

// Generated by the owning public-event projection test; no production data.
test('public process is disclosed while answer chunks, terminal fragments and replay stay visible', {
  ...(process.env.ISSUE275_SNAPSHOTS ? {} : { skip: 'Requires synthetic public-event snapshots from the owning test.' }),
}, async ({ app, browser, screen }) => {
  const snapshots = JSON.parse(readFileSync(process.env.ISSUE275_SNAPSHOTS!, 'utf8'))
  const send = (name: string) => browser.evaluate((snapshot) => {
    window.dispatchEvent(new CustomEvent('native-streaming-snapshot', { detail: snapshot }))
    return true
  }, snapshots[name])
  const activity = () => browser.locator('[data-slot="run-activity"]')
  const toggle = () => browser.locator('[data-slot="run-activity"] button').first()
  const settle = () => browser.evaluate(async () => {
    await Promise.all(document.getAnimations().filter(animation => animation.effect?.getTiming().iterations !== Infinity)
      .map(animation => animation.finished.catch(() => {})))
    return true
  })
  await app.open('/e2e/native-streaming.html')
  await send('running')
  await expect(screen.getByText('Substantive answer.', { exact: true })).toBeVisible()
  await expect(activity()).toBeVisible()
  await toggle().tap()
  await expect(screen.getByText('Public tool preamble.', { exact: true })).toBeVisible()
  expect(await browser.evaluate(() => document.querySelector('[data-slot="run-activity"]')?.textContent?.includes('Substantive answer.') ?? false)).toBe(false)
  await toggle().tap()
  await expect(screen.getByText('Substantive answer.', { exact: true })).toBeVisible()
  await screen.getByRole('textbox', '响应检查').fill('still responsive')
  await settle()
  await app.screenshot('react-public-running-collapsed')
  for (const terminal of ['failed','cancelled']) {
    await send(terminal)
    await expect(screen.getByText('Partial useful answer.', { exact: true })).toBeVisible()
    await expect(activity()).toHaveAttribute('data-status',terminal === 'failed' ? 'error' : 'cancelled')
  }
  await send('completed')
  await expect(screen.getByText('Verified final answer.', { exact: true })).toBeVisible()
  await toggle().tap()
  for (const text of ['First public process.','Later public process.']) await expect(screen.getByText(text, { exact: true })).toBeVisible()
  expect(await browser.evaluate(() => document.body.textContent?.split('Verified final answer.').length)).toBe(2)
  expect(await browser.evaluate(() => /查看全部活动|查看需要注意的记录|显示更多活动/.test(document.body.textContent ?? ''))).toBe(false)
  await settle()
  await app.screenshot('react-public-final-expanded')
  await browser.reload()
  await send('completed')
  await expect(screen.getByText('Verified final answer.', { exact: true })).toBeVisible()
  await toggle().tap()
  for (const text of ['First public process.','Later public process.']) await expect(screen.getByText(text, { exact: true })).toBeVisible()
  await settle()
  await app.screenshot('react-public-replayed')
})
